-- ============================================================================
-- payer-rules-oh-appendixdd-mco4.sql
--
-- Appendix DD determinations for the four Ohio Medicaid plans that never had
-- them: Buckeye, CareSource, Molina and UnitedHealthcare Community Plan.
-- Three codes each — G0179, G0180 (home health plan-of-care certification and
-- re-certification) and 99343 (home visit, new patient).
--
-- WHY THIS FILE EXISTS: A ROW WITH NO SEED BEHIND IT IS NOT IN THE LIBRARY
-- These twelve determinations already existed in one developer database under
-- created_by 'extract:state-fee-schedule-2026-08' — an extraction run that was
-- never committed as a seed. No file in db/seed/MANIFEST produced them, so
-- production, which is built by running the manifest, never had them. Every
-- local check that read those rows passed on data that existed nowhere else.
--
-- It surfaced by accident. A migration written to repair those rows reported 8
-- restored locally and 0 on production; chasing that difference is what found
-- the twelve. Humana Healthy Horizons of Ohio was unaffected because it has its
-- own committed seed (payer-rules-oh-appendixdd-humana.sql) covering the same
-- three codes from the same document — which is why the determinations below
-- are byte-for-byte the same determinations, from the same source_document, and
-- why Humana is deliberately NOT in this file. Two seeds writing one key would
-- put two live rules on it and fetchPayerRule ends in LIMIT 1 with no tiebreak.
--
-- THE GROUNDING
--   G0179, G0180  Absent from all 8 tabs of the workbook; the literal string
--                 does not occur anywhere in the archive. Bracket G0138 -> G0202.
--                 The blanket exclusion note denies unlisted codes in the ranges
--                 it enumerates, the first of which is G0001-G9999.
--   99343         Present, and explicitly killed: "MSRIAP schedule" tab, status
--                 code 3 (discontinued coverage), payment indicator D, which the
--                 schedule's key defines as DISCONTINUED PROCEDURE CODE,
--                 effective 01/01/2023. CPT deleted the code that same year.
--                 effective_date is 2023-01-01, not the document revision date,
--                 so a claim re-worked at a back-dated date of service inside
--                 the timely-filing window gets the answer that was true then.
-- ============================================================================

BEGIN;

UPDATE payer_rule pr
   SET expiration_date = GREATEST(pr.effective_date, DATE '2023-01-01')
 WHERE pr.expiration_date IS NULL
   AND pr.created_by <> 'extract:oh-appendixdd-mco4-2026-08'
   AND pr.state = 'OH' AND pr.attribute = 'covered'
   AND pr.code IN ('G0179', 'G0180', '99343')
   AND pr.payer_id IN ('a0000000-0000-4000-8000-000000000306'::uuid, 'a0000000-0000-4000-8000-000000000305'::uuid, 'a0000000-0000-4000-8000-000000000307'::uuid, 'a0000000-0000-4000-8000-000000000302'::uuid);

INSERT INTO payer_rule (id, payer_id, state, product_line, code, attribute, value, coverage_status, confidence, effective_date, expiration_date, source_doc_id, source_quote, created_by)
VALUES
  ('e92cf541-abc6-41ed-863a-418e3a2f1318'::uuid, 'a0000000-0000-4000-8000-000000000306'::uuid, 'OH', 'medicaid_mco', 'G0179', 'covered', '{"answer":"Not covered by Ohio Medicaid. Appendix DD to rule 5160-1-60, revised 01/01/2026, does not list G0179 (physician re-certification of a home health agency plan of care) on any of its 8 tabs — the two codes either side of it are consecutive (G0138 followed directly by G0202), and the literal string \"G0179\" does not occur anywhere in the workbook. The schedule''s blanket exclusion note states that codes in the listed ranges are not covered unless otherwise indicated, and the first range listed is G0001-G9999. G0179 falls inside it and is not otherwise indicated, so Buckeye Health Plan follows a state denial. Humana Healthy Horizons of Ohio already carried this determination from the same document; the other four plans did not, which is what this file fixes.","source":"Appendix DD to rule 5160-1-60, blanket exclusion note","rateBasis":null,"stateFfsRate":null}'::jsonb, 'not_covered', 0.85, DATE '2026-01-01', NULL, 'c83c573f-ef17-4117-8ede-8e141a4b1431'::uuid, 'Appendix DD to rule 5160-1-60, blanket exclusion note — Unless otherwise indicated, services and items represented by codes in the following ranges are not covered.', 'extract:oh-appendixdd-mco4-2026-08'),
